CREATE FUNCTION c1_api.code_check(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE d c1_private.deployment;s c1_private.sessions;c c1_private.display_credentials;v c1_private.vouchers;u c1_private.units;BEGIN d=c1_private.guard(n,true,(q->>'mutation_id')::uuid);s=c1_private.auth(n,q,true);PERFORM c1_private.owner_auth(n,s,q->>'store','redeem');SELECT * INTO c FROM c1_private.display_credentials WHERE ns=n AND hash=c1_private.h(q->>'display_hash') AND active AND valid_until>d.now AND credential_epoch=d.credential_epoch;IF NOT FOUND THEN PERFORM c1_private.fail('INVALID_CODE');END IF;SELECT * INTO v FROM c1_private.vouchers WHERE ns=n AND id=c.voucher;SELECT * INTO u FROM c1_private.units WHERE ns=n AND store=v.store AND seq=v.seq;IF v.store<>q->>'store' OR v.access_epoch<>c.access_epoch OR v.display_epoch<>c.epoch OR u.generation<>v.generation OR u.bucket<>'R' OR u.lock_id IS NOT NULL OR u.active_op IS NOT NULL OR d.now>=v.expires_at OR NOT EXISTS(SELECT 1 FROM c1_private.sessions WHERE ns=n AND hash=c.session_hash AND NOT revoked AND epoch=d.credential_epoch) OR (SELECT paused FROM c1_private.stores WHERE ns=n AND store=u.store) OR c1_private.window_end((SELECT windows FROM c1_private.terms WHERE ns=n AND store=u.store AND meal=u.meal AND version=u.version),d.now)=0 THEN PERFORM c1_private.fail('INVALID_CODE');END IF;IF NOT c1_private.content_available(n,u.store,u.meal,u.version) THEN PERFORM c1_private.fail('CONTENT_UNAVAILABLE');END IF;RETURN jsonb_build_object('valid',true,'voucher',v.id,'generation',v.generation::text,'terms',c1_private.term_dto(n,u.store,u.meal,u.version),'validUntil',c.valid_until);END $$;
CREATE FUNCTION c1_api.lock_confirm(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE d c1_private.deployment;s c1_private.sessions;valid jsonb;v c1_private.vouchers;old jsonb;res jsonb;gr bigint;BEGIN d=c1_private.guard(n,false,(q->>'mutation_id')::uuid);s=c1_private.auth(n,q,true);gr=c1_private.owner_auth(n,s,q->>'store','redeem');old=c1_private.idem(n,s,'lock',q);IF old IS NOT NULL THEN RETURN old;END IF;-- Exact display/epoch/current owner checks repeated in the same guard transaction.
 valid=c1_api.code_check(n,q);SELECT * INTO v FROM c1_private.vouchers WHERE ns=n AND id=valid->>'voucher' FOR UPDATE;
 res=c1_private.new_intent(n,s,'lock',q,jsonb_build_object('store',v.store,'voucher_id',v.id,'generation',v.generation::bigint,'deadline',least(d.now+300,v.expires_at),'seq',v.seq),false,gr);UPDATE c1_private.units SET active_op=(res->>'id')::uuid WHERE ns=n AND store=v.store AND seq=v.seq;
 UPDATE c1_private.access_credentials SET active=false WHERE ns=n AND voucher=v.id;UPDATE c1_private.display_credentials SET active=false WHERE ns=n AND voucher=v.id;UPDATE c1_private.vouchers SET access_epoch=access_epoch+1,display_epoch=display_epoch+1 WHERE ns=n AND id=v.id;RETURN res;END $$;
CREATE FUNCTION c1_api.handover_confirm(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE d c1_private.deployment;s c1_private.sessions;u c1_private.units;v c1_private.vouchers;gr bigint;old jsonb;res jsonb;we bigint;BEGIN d=c1_private.guard(n);s=c1_private.auth(n,q,true);gr=c1_private.owner_auth(n,s,q->>'store','redeem');old=c1_private.idem(n,s,'handover',q);IF old IS NOT NULL THEN RETURN old;END IF;PERFORM c1_private.guard(n,true);SELECT * INTO u FROM c1_private.units WHERE ns=n AND store=q->>'store' AND lock_id=q->>'case_id';IF NOT FOUND OR u.bucket<>'R' OR u.marker_id IS NOT NULL OR u.active_op IS NOT NULL OR (SELECT paused FROM c1_private.stores WHERE ns=n AND store=u.store) THEN PERFORM c1_private.fail('NOT_LOCKED');END IF;SELECT * INTO v FROM c1_private.vouchers WHERE ns=n AND id=u.voucher_id;SELECT c1_private.window_end(windows,d.now) INTO we FROM c1_private.terms WHERE ns=n AND store=u.store AND meal=u.meal AND version=u.version;IF d.now>=v.expires_at OR we=0 THEN PERFORM c1_private.fail('EXPIRED');END IF;IF NOT c1_private.content_available(n,u.store,u.meal,u.version) THEN PERFORM c1_private.fail('CONTENT_UNAVAILABLE');END IF;res=c1_private.new_intent(n,s,'handover',q,jsonb_build_object('store',u.store,'seq',u.seq,'voucher_id',v.id,'generation',v.generation::bigint,'lock_id',u.lock_id,'manual_authorization',encode(sha256(convert_to(q->>'new_id'||encode(s.hash,'hex')||gr::text,'UTF8')),'hex'),'deadline',least(d.now+30,v.expires_at,we)),false,gr);UPDATE c1_private.units SET active_op=(res->>'id')::uuid WHERE ns=n AND store=u.store AND seq=u.seq;RETURN res;END $$;
CREATE FUNCTION c1_api.settle_review(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE d c1_private.deployment;s c1_private.sessions;u c1_private.units;p jsonb;BEGIN d=c1_private.guard(n);s=c1_private.auth(n,q,true);PERFORM c1_private.owner_auth(n,s,q->>'store','payout');SELECT * INTO u FROM c1_private.units WHERE ns=n AND store=q->>'store' AND voucher_id=q->>'id' AND bucket='H';IF NOT FOUND OR u.active_op IS NOT NULL THEN PERFORM c1_private.fail('NOT_FOUND');END IF;p=jsonb_build_object('store',u.store,'voucher_id',u.voucher_id,'generation',u.generation::bigint,'seq',u.seq,'amount',u.price::text);INSERT INTO c1_private.reviews VALUES(n,(q->>'review_id')::uuid,s.subject,'settle',p,d.now+300);RETURN jsonb_build_object('reviewId',q->>'review_id','amount',u.price::text,'expiresAt',d.now+300);END $$;
CREATE FUNCTION c1_api.settle_confirm(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE d c1_private.deployment;s c1_private.sessions;r c1_private.reviews;u c1_private.units;old jsonb;res jsonb;gr bigint;BEGIN d=c1_private.guard(n);s=c1_private.auth(n,q,true);gr=c1_private.owner_auth(n,s,q->>'store','payout');old=c1_private.idem(n,s,'settle',q);IF old IS NOT NULL THEN RETURN old;END IF;PERFORM c1_private.guard(n,true);SELECT * INTO r FROM c1_private.reviews WHERE ns=n AND id=(q->'client'->>'reviewId')::uuid AND subject=s.subject AND kind='settle';IF NOT FOUND OR r.expires<=d.now THEN PERFORM c1_private.fail('STALE_REVIEW');END IF;SELECT * INTO u FROM c1_private.units WHERE ns=n AND store=r.payload->>'store' AND seq=(r.payload->>'seq')::int;IF u.bucket<>'H' OR u.active_op IS NOT NULL THEN PERFORM c1_private.fail('CONFLICT');END IF;IF NOT c1_private.content_available(n,u.store,u.meal,u.version) THEN PERFORM c1_private.fail('CONTENT_UNAVAILABLE');END IF;res=c1_private.new_intent(n,s,'settle',q,r.payload||jsonb_build_object('deadline',d.now+300),true,gr);UPDATE c1_private.units SET active_op=(res->>'id')::uuid WHERE ns=n AND store=u.store AND seq=u.seq;RETURN res;END $$;
CREATE FUNCTION c1_api.refund_review(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE d c1_private.deployment;s c1_private.sessions;o c1_private.orders;b c1_private.payer_bindings;mask int=0;u c1_private.units;p jsonb;BEGIN d=c1_private.guard(n);s=c1_private.auth(n,q,true);SELECT * INTO o FROM c1_private.orders WHERE ns=n AND id=(q->>'id')::uuid AND subject=s.subject;IF NOT FOUND THEN PERFORM c1_private.fail('NOT_FOUND');END IF;SELECT * INTO b FROM c1_private.payer_bindings WHERE ns=n AND subject=s.subject AND enabled AND address=o.payer;IF NOT FOUND THEN PERFORM c1_private.fail('PAYER_REQUIRED');END IF;FOR u IN SELECT * FROM c1_private.units WHERE ns=n AND order_id=o.id ORDER BY local_index LOOP IF u.bucket='A' AND u.active_op IS NULL THEN mask=mask|(1<<u.local_index);END IF;END LOOP;IF mask=0 THEN PERFORM c1_private.fail('NO_SAFE_UNITS');END IF;p=jsonb_build_object('store',o.store,'order_id',o.id,'mask',mask,'payer',o.payer,'batch_id',(SELECT payload->>'batch_id' FROM c1_private.intents WHERE ns=n AND id=o.id));INSERT INTO c1_private.reviews VALUES(n,(q->>'review_id')::uuid,s.subject,'refund',p,d.now+300);RETURN jsonb_build_object('reviewId',q->>'review_id','mask',mask,'expiresAt',d.now+300);END $$;
CREATE FUNCTION c1_api.refund_confirm(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE d c1_private.deployment;s c1_private.sessions;r c1_private.reviews;old jsonb;res jsonb;BEGIN d=c1_private.guard(n);s=c1_private.auth(n,q,true);IF NOT EXISTS(SELECT 1 FROM c1_private.payer_bindings WHERE ns=n AND subject=s.subject AND enabled) THEN PERFORM c1_private.fail('PAYER_REQUIRED');END IF;old=c1_private.idem(n,s,'refund',q);IF old IS NOT NULL THEN RETURN old;END IF;PERFORM c1_private.guard(n,true);SELECT * INTO r FROM c1_private.reviews WHERE ns=n AND id=(q->'client'->>'reviewId')::uuid AND subject=s.subject AND kind='refund';IF NOT FOUND OR r.expires<=d.now THEN PERFORM c1_private.fail('STALE_REVIEW');END IF;IF EXISTS(SELECT 1 FROM c1_private.units WHERE ns=n AND order_id=(r.payload->>'order_id')::uuid AND ((r.payload->>'mask')::int & (1<<local_index))<>0 AND (bucket<>'A' OR active_op IS NOT NULL)) THEN PERFORM c1_private.fail('CONFLICT');END IF;res=c1_private.new_intent(n,s,'refund',q,r.payload||jsonb_build_object('deadline',d.now+300),true);UPDATE c1_private.units SET active_op=(res->>'id')::uuid WHERE ns=n AND order_id=(r.payload->>'order_id')::uuid AND ((r.payload->>'mask')::int & (1<<local_index))<>0;RETURN res;END $$;
